\-- 1\. Membuat Trigger Function CREATE OR REPLACE FUNCTION trg\_update\_stock\_and\_journal() RETURNS TRIGGER AS $$ DECLARE v\_current\_stock INT; BEGIN -- Mengunci dan mengambil stok barang saat ini untuk mencegah race condition SELECT stock\_qty INTO v\_current\_stock FROM inventory\_items WHERE item\_id = NEW.item\_id FOR UPDATE; -- Validasi keberadaan barang pada master inventory IF NOT FOUND THEN RAISE EXCEPTION 'Item dengan ID % tidak ditemukan pada master inventory\_items.', NEW.item\_id; END IF; -- Pemrosesan logika berdasarkan jenis transaksi (trx\_type) IF NEW.trx\_type = 'PURCHASE' THEN -- Pembelian menambah jumlah stok fisik UPDATE inventory\_items SET stock\_qty = stock\_qty + NEW.qty WHERE item\_id = NEW.item\_id; ELSIF NEW.trx\_type = 'SALE' THEN -- Pengecekan batas stok (anti-negative inventory prevention) IF (v\_current\_stock - NEW.qty) &lt; 0 THEN RAISE EXCEPTION 'Transaksi SALE dibatalkan! Stok tidak mencukupi untuk item % (Stok tersedia: %, Dibeli: %).', NEW.item\_id, v\_current\_stock, NEW.qty; END IF; -- Penjualan mengurangi jumlah stok fisik UPDATE inventory\_items SET stock\_qty = stock\_qty - NEW.qty WHERE item\_id = NEW.item\_id; ELSIF NEW.trx\_type = 'ADJUSTMENT' THEN -- Penyesuaian stok (bisa menambah atau mengurangi tergantung nilai NEW.qty) IF (v\_current\_stock + NEW.qty) &lt; 0 THEN RAISE EXCEPTION 'Transaksi ADJUSTMENT dibatalkan! Penyesuaian menyebabkan stok negatif untuk item % (Stok tersedia: %, Penyesuaian: %).', NEW.item\_id, v\_current\_stock, NEW.qty; END IF; UPDATE inventory\_items SET stock\_qty = stock\_qty + NEW.qty WHERE item\_id = NEW.item\_id; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql; -- 2\. Memasang Trigger pada Tabel inventory\_transactions CREATE OR REPLACE TRIGGER trg\_update\_stock\_and\_journal BEFORE INSERT ON inventory\_transactions FOR EACH ROW EXECUTE FUNCTION trg\_update\_stock\_and\_journal();
